//! The registration cases of WebAuthn Level 3, section 16 (Test Vectors). `README.md` gives the source.

/// A registration case: its challenge, its credential ID, its `clientDataJSON`, and its attestation object, each as
/// hexadecimal text.
pub(crate) struct Vector {
    pub challenge: &'static str,
    pub credential_id: &'static str,
    pub client_data: &'static str,
    pub attestation: &'static str,
}

